  color: #fff;
}

.fd-btn-save:hover {
  background: #1976d2;
}

/* ── Chart area ───────────────────────────────────────── */
.fd-chart-area {
  flex: 1;
  position: relative;
  overflow: hidden;
}

.fd-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: rgba(255, 255, 255, 0.25);
  text-align: center;
  padding: 24px;
}

.fd-empty mat-icon {
